        ["lite_terrain_single_fetch"] = ("Lighter ground shader", "A smaller shader for unpainted ground. The same picture."),
        ["lite_skip_black_lights"] = ("Skip unlit lights", "Shaders skip lights that add nothing. The same picture, faster."),
        [Refii.AndroidRuntime.AndroidGroundShading.Key] = ("Ground contact shading",
            "The soft shadow where objects meet the ground, under the modern lighting. Near the ground is the same picture, faster; Fast is softer along long walls; Fastest also softer on the ground at their foot; Off removes it. Applies at the next start."),
        [Refii.AndroidRuntime.AndroidGroundShading.GatherKey] = ("Grouped ground-shadow reads",
            "The ground-contact shadow read in fewer, grouped texture reads. The same picture. Applies at the next start."),
        [Refii.Models.Engine_ShaderSpecialisation.TerrainBitLoopKey] = ("Lighter ground layers",
            "The ground's shader looks only at the surfaces painted nearby. The same picture. Applies at the next start."),
        [Refii.Models.Engine_ShaderSpecialisation.TerrainMaxLayersKey] = ("Ground layers per spot",
